<span class="line"><span style="color:#C678DD;">    def</span><span style="color:#61AFEF;"> find_path_between_diseases</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;font-style:italic;">self</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">disease1</span><span style="color:#ABB2BF;">: </span><span style="color:#56B6C2;">str</span><span style="color:#ABB2BF;">, </span><span style="color:#D19A66;font-style:italic;">disease2</span><span style="color:#ABB2BF;">: </span><span style="color:#56B6C2;">str</span><span style="color:#ABB2BF;">) -&gt; list[</span><span style="color:#56B6C2;">dict</span><span style="color:#ABB2BF;">]:</span></span>
